css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .74); position: relative; }
.loader .drum { position: absolute; left: 12%; top: 6%; width: 50%; height: 68%; border-radius: 50%; background: repeating-conic-gradient(from 0deg at 50% 50%, var(--accent) 0 12%, color-mix(in srgb, #fff 26%, var(--accent)) 0 24%); transform: rotate(-16deg); animation: mixer-turn calc(var(--loader-speed) * 2.2) linear infinite; }
.loader .chute { position: absolute; left: 62%; top: 34%; width: 30%; height: 16%; border-radius: 4px 8px 8px 4px; background: linear-gradient(var(--accent-2), color-mix(in srgb, #000 25%, var(--accent-2))); transform: rotate(16deg); }
.loader .frame { position: absolute; left: 6%; right: 6%; bottom: 20%; height: 14%; border-radius: 4px; background: linear-gradient(var(--accent-2), color-mix(in srgb, #000 30%, var(--accent-2))); }
.loader .wheel { position: absolute; bottom: 2%; width: 20%; height: 26%; border-radius: 50%; background: radial-gradient(circle, #64748b 0 30%, #1e293b 32%); animation: mixer-roll calc(var(--loader-speed) * 2.2) linear infinite; }
.loader .wheel:nth-of-type(4) { left: 12%; }
.loader .wheel:nth-of-type(5) { right: 12%; }
@keyframes mixer-turn { from { transform: rotate(-16deg); } to { transform: rotate(344deg); } }
@keyframes mixer-roll { to { transform: rotate(1turn); } }
